"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["316"],{7835(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>h,frontMatter:()=>a,contentTitle:()=>i,toc:()=>l,assets:()=>c});var o=JSON.parse('{"id":"reference/admin/howtos/resellerAccount","title":"How to work with ALMS Reseller Accounts","description":"almsc \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/admin/howtos/resellerAccount.md","sourceDirName":"reference/admin/howtos","slug":"/reference/admin/howtos/resellerAccount","permalink":"/personal-av-docs/docs/reference/admin/howtos/resellerAccount","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/admin/howtos/resellerAccount.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to work with ALMS Reseller Accounts","sidebar_label":"How to work with ALMS Reseller Accounts","sidebar_position":99,"edition":"almsc","source":"https://doc.airvantage.net/almsc/reference/admin/howtos/resellerAccount","format":"md"}}'),s=n(4848),r=n(8453);let a={title:"How to work with ALMS Reseller Accounts",sidebar_label:"How to work with ALMS Reseller Accounts",sidebar_position:99,edition:"almsc",source:"https://doc.airvantage.net/almsc/reference/admin/howtos/resellerAccount",format:"md"},i,c={},l=[];function u(e){let t={a:"a",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsxs)(t.p,{children:[":::note Edition\n",(0,s.jsx)(t.strong,{children:"almsc"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,s.jsx)(t.a,{href:"https://doc.airvantage.net/almsc/reference/admin/howtos/resellerAccount",children:"Original page"}),".\n:::"]}),"\n",(0,s.jsx)(t.p,{children:"How to work with ALMS Reseller Accounts\nAn ALMS Reseller account is made available at no cost to all authorized Semtech AirLink Partners\n1\n. The account is provided to AirLink Partners to help you to manage your customer base. It provides visibility into all ALMS accounts that are partnered with your ALMS Reseller account and provides tools to help your customers with account creation, managing renewals, and transferring devices from your account to a customer\u2019s account to assist with trials and proof of concepts.\nThe account is also provided to AirLink Partners to give you a test environment with access to the complete range of Semtech products and services, allowing you to demo AirLink features to customers.\n1\nIf you are an authorized Semtech Partner and you do not have an ALMS Reseller account, please reach out to your Channel Business Manager or Semtech Customer Support to have an account created.\nInitializing Table Of Contents...\nALMS Reseller Accounts \u2013 Key Features\nThere are several key features of an ALMS Reseller account:\nFree AirLink Services for up to 20 AirLink Routers:\nYou can have a maximum of 20 devices in your ALMS Reseller account, eligible to use all AirLink Services on all device types, and those services automatically renew every five years at no cost. This allows you to try all AirLink Services at no cost, ensuring you are able to position the value of AirLink Services to your customers. For operational activities, please create a standard ALMS account. Note that this type of account does not support Semtech connectivity or SIM cards. Please speak with your Channel Business Manager if you are interested in\nthose services\n.\nCustomers Page:\nThe Customers page displays your partnered accounts and provides insight into the status of each account\u2019s systems. It gives you an all-in-one view of the information you need to manage your customers. This page replaces the Subaccounts page from previous ALMS Reseller Accounts. See\nthe Customers section\nbelow for full details on this page.\nCreate an Account:\nYou can create a new ALMS account on behalf of your customer. See\nCreate an Account\nbelow for more details.\nDirect Device Registration:\nALMS Reseller accounts allow you to register new AirLink devices into any ALMS account. You can register devices to multiple accounts at the same time and register multiple models of routers at the same time. For full details on this feature, refer to\nHow to register systems to multiple customers\n.\nDevice Transfer:\nYou can transfer devices between your account and any partnered account. As devices in your ALMS Reseller account are free to use, transferring to a standard ALMS account will activate services as if the device was new. See\nDevice Transfer\nbelow for more information.\nAirLink Services Renewal Notifications:\nYour ALMS Reseller account helps you track device service dates and renewals. For every partnered ALMS account, you will receive monthly renewal notifications via email. The email includes a .csv file for each customer, with details of each device coming up for renewal. Please note that you need to have at least one user configured as an Admin user in order to receive notifications.\nCustomers Page\nThe Customers page shows you your partnered accounts and provides insight into the status of each account\u2019s systems. It gives you an all-in-one view of the information you need to manage your customers.\nEach customer row shows:\nName:\nThe ALMS account name. You may need this information when communicating with Customer Support. Clicking on the name will open a new browser window and log you into the customer\u2019s account, provided you have appropriate privileges to access the account.\nUID:\nThe account identifier (UID). This is the formal identifier of the account. This is the best information to provide to Customer Support to identify a customer\u2019s ALMS account.\nTotal Systems:\nProvides a count of the total number of systems in the customer\u2019s ALMS account.\nActive Systems:\nProvides a count of the number of active systems in the customer\u2019s ALMS account.\nInitial Renewal:\nThe first date that the services on a system in the customer\u2019s ALMS account will expire. This is the date that the services in the customer\u2019s ALMS account will need to be renewed.\nRenewal Systems:\nThe column reflects the number of systems that are up for renewal on the date listed in \u201CInitial Renewal\u201D.\nRenewal Dates:\nThe three columns with the colored circles list the number of devices in the customer\u2019s account that have services that will expire within the time periods:\nGreen = Services will expire in over 120 days\nYellow = Services will expire between 120 and 60 days\nRed = Services will expire in under 60 days\nClicking any of the colored circles will open the Customer account (assuming you have appropriate access rights) on the\nMonitor > Systems\npage, filtered to the list of devices.\nPartner Profile:\nThis column displays the User Profile that users from your ALMS Reseller account have when accessing your customer\u2019s ALMS account.\nLast Login Date:\nThis column shows you how active your customers have been in using ALMS. It displays the last time a user from your customer\u2019s ALMS account logged in.\nAdministrators:\nThis column displays all the Administrator users for each customer ALMS account\u2014 it gives you a point of contact for your customers. If there is more than one administrator, a \u201C+\u201D will indicate how many, and clicking on the number will open a new window to display the list of users.\nYou can sort your accounts by Name and all other numerical fields.\nAs an ALMS Reseller, your Administrator users will receive monthly renewal notifications via email for each partnered account. The message includes an attached .csv file for each customer with details of each device. Note that in cases where a customer account is associated with more than one ALMS Reseller account, all partnered ALMS Reseller accounts will receive the renewal notification messages.\nCreate an Account\nYou can now create an ALMS account directly on behalf of your customers. The new account will be automatically partnered with your Reseller account.\nTo create a new ALMS customer account, on the Customers page, click\n+\nat the top right-hand corner.\nThe new account name and account administrator email address must be unique (not used by any other customer account in ALMS), otherwise ALMS will generate an error message.\nWhen the account is created, your customer will receive a notification asking them to set their password and finalize the account creation process. They will have 7 days to activate the new account.\nBy default users from your ALMS Reseller account will be given a new, default user profile that provides read-only access to the new customer account. As with any account, you can directly register devices to the account. If you need greater access, your customer can assign a different profile with more rights, at their discretion.\nDirect Device Registration\nALMS Reseller accounts provide the capability to register new AirLink devices into any ALMS account. This simplified process allows you to register to multiple accounts at the same time and to register multiple models of routers at the same time. For full details on this feature, refer to\nHow to register systems to multiple customers\n.\nFor general instructions on how to register routers, please see\nHow to register a list of systems\n.\nDevice Transfer\nWhen transferring devices between an ALMS Reseller and standard customer accounts, be aware that device behavior will change depending on which account it is in. While the device is in the ALMS Reseller account, services are enabled by default and the devices automatically renew every 5 years. After transferring to the customer\u2019s account, the device will activate as if new, on the default services for the device model.\nTo transfer one or more devices, select them on the\nMonitor > Systems\npage, and then click Transfer.\nNote that devices in ALMS Reseller accounts still adhere to the standard limitations of AirLink Services. For example, if a device stays in your ALMS Reseller account for three years and you try to transfer it to a customer account, it will be past its one year of included service and the device will not transfer to the customer account (an error indicates that the service allocation is missing or expired). In this case, before the device can be transferred, you must either:\nRenew service on the device\nSuspend service. After transferring the suspended device, it will be in the Inventory state in the customer account. You can renew service at any time after transfer.\nWhen transferring devices between accounts, you can only transfer devices under the same offer type. For example, devices on AirLink Premium in your ALMS Reseller account must be transferred to an AirLink Premium offer in the customer\u2019s account.\nAdministration\nUnder Administration, you can view your account details, manage security options, administrators, users and user profiles, partnerships and connection to external accounts used for subscription management and SMS sending.\nFor information about Administration features, see the\nAdministration page\n.\nAccount\nOffers\nSupport\nUsers\nProfiles\nPartners (see below)\nSecurity\nOperator Accounts\nSMS Accounts\nChannel Business Managers\nThis section lists the Semtech Channel Business Managers that are assigned to your account. You can use these contacts to request sales assistance with your customers, get help with renewals, or any other general questions. These contacts will receive renewal notifications related to the customers that are partnered with your ALMS Reseller account, to ensure that we can properly assist you with the renewal process.\nThe contacts in this section are managed by Semtech and should not be edited. If you have questions or concerns about the list of contacts, or if the list is not populated, please contact Customer Support.\nReseller Account Partners Page\nThe Partners page in a Reseller account has a column showing the account UID, Account Details action, the account type and administrators.\nTo view account details, click the icon in the Actions column."})]})}function h(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}},8453(e,t,n){n.d(t,{R:()=>a,x:()=>i});var o=n(6540);let s={},r=o.createContext(s);function a(e){let t=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),o.createElement(r.Provider,{value:t},e.children)}}}]);